r.append(R(7203090,"ब्लूबेरी और नींबू चीज़केक","नींबू के तीखे स्वाद वाला फलों से भरा चीज़केक। एक बेहतरीन मीठा व्यंजन।","1","172 ग्राम",
["आधे नींबू का ज़ेस्ट, बारीक कद्दूकस किया हुआ","1 छोटा चम्मच नींबू का रस","1 समतल छोटा चम्मच लेमन कर्ड","1 ढेर वाला बड़ा चम्मच फ़ैट-फ़्री क्रीम चीज़ (लगभग 60 ग्राम)","80 ग्राम ब्लूबेरी","2 मोटे ओटकेक, कुचले हुए"],
["एक कटोरे में नींबू का ज़ेस्ट, लेमन कर्ड और क्रीम चीज़ को एक साथ मिलाएँ।","आधी ब्लूबेरी को कांटे से हल्के हाथ से कुचलें और उसमें नींबू का रस मिलाएँ।","बची हुई ब्लूबेरी को क्रीम चीज़ और लेमन कर्ड के मिश्रण में डालें।","कुचली हुई ब्लूबेरी को गिलास की तली में रखें, उसके ऊपर लेमन चीज़ का मिश्रण डालें, ओटकेक का चूरा छिड़कें और थोड़े नींबू के ज़ेस्ट तथा एक ब्लूबेरी से सजाएँ।"]))
r.append(R(7204791,"वेजी चिली बाउल","यह स्वादिष्ट और दिल को सुकून देने वाली शाकाहारी चिली एक ही बर्तन में बनने वाला कमाल का व्यंजन है। इसमें कई तरह के मसाले, सब्ज़ियाँ और भरपूर शाकाहारी कीमा मिलाया जाता है, जो रात के खाने में तीखा स्वाद लाता है। इस रेसिपी को Slimming World के साथ साझेदारी में चुना गया है।","4","612 ग्राम",
["कम कैलोरी वाला कुकिंग स्प्रे","1 बड़ा प्याज़, बारीक कटा हुआ","2 डंठल सेलरी, बारीक कटी हुई","3 लाल शिमला मिर्च, बीज निकाली हुई और बारीक कटी हुई","2 लहसुन की फांक, कुचली हुई","1½ छोटा चम्मच तीखी स्मोक्ड पेपरिका","1½ छोटा चम्मच पिसा जीरा","2 x 400 ग्राम के डिब्बे कटे हुए टमाटर","100 मिलीलीटर पानी","300 ग्राम जमा हुआ सादा सोया/वेजिटेबल प्रोटीन कीमा","1 x 400 ग्राम का डिब्बा लाल राजमा, छाना और धोया हुआ","150 ग्राम फ़ैट-फ़्री सादा बिना चीनी वाला ग्रीक दही, परोसने के लिए","20 ग्राम ताज़ा धनिये की टहनियाँ","1 नींबू, फांकों में कटा हुआ, परोसने के लिए"],
["एक बड़े, भारी तले वाले, ढक्कन वाले नॉन-स्टिक सॉसपैन या आग पर रखने योग्य कैसरोल डिश में कुकिंग स्प्रे की दो-तीन बार स्प्रे करें और उसे धीमी-मध्यम आँच पर रखें। प्याज़, सेलरी और शिमला मिर्च डालें। ढककर 8-10 मिनट तक नरम होने तक भूनें और बीच-बीच में चलाते रहें (अगर सब्ज़ियाँ बर्तन में चिपकने लगें तो थोड़ा पानी छिड़कें)।","लहसुन, पेपरिका और जीरा डालें और 1 मिनट तक खुशबू आने तक पकाएँ। 100 मिलीलीटर पानी के साथ टमाटर डालकर चलाएँ और उबाल आने दें। आँच कम करें और 2-3 मिनट तक हल्की आँच पर पकाएँ, जब तक कि यह थोड़ा गाढ़ा न हो जाए।","कीमा और राजमा डालकर चलाएँ और 20 मिनट और पकाएँ, जब तक कि यह गाढ़ा न हो जाए। काली मिर्च डालें।","चिली को कटोरों में परोसें और ऊपर से दही डालें। ऊपर से थोड़ी काली मिर्च पीसकर डालें, धनिया डालें और नींबू की फांकों के साथ परोसें।"],
["आप अपनी पसंद का सादा दही इस्तेमाल कर सकते हैं। लेकिन इससे पोषण संबंधी जानकारी और व्यंजन की बनावट बदल जाएगी।",FV(4)]))
r.append(R(7205275,"क्रैनबेरी सॉस","क्रिसमस के साथ परोसी जाने वाली पारंपरिक और खट्टी-मीठी चटनी।","8","53 ग्राम",
["350 ग्राम ताज़ी क्रैनबेरी","3 बड़े चम्मच पोर्ट","1 संतरे का कद्दूकस किया हुआ छिलका और रस","स्वाद अनुसार तेज़ मिठास वाला स्वीटनर या चीनी"],
["क्रैनबेरी, पोर्ट, संतरे का छिलका और रस एक पैन में डालें।","ढककर 8-10 मिनट तक हल्की आँच पर पकाएँ, जब तक कि क्रैनबेरी नरम और रसीली न हो जाएँ।","स्वाद अनुसार स्वीटनर या चीनी मिलाएँ।","ठंडा करें और ज़रूरत तक फ्रिज में रखें।"],
["थोड़ा अलग स्वाद के लिए क्रैनबेरी के साथ एक बारीक कटा ब्रैमली सेब भी डालकर देखें।","पोर्ट को छानने में जानवरों से मिलने वाली चीज़ों का उपयोग हो सकता है, इसलिए अगर आप शाकाहारी/वीगन हैं तो लेबल दोबारा जाँच लें।","फ्रीज़ करने के निर्देश: भागों में फ्रीज़ करें, फिर पिघलाकर ठंडा या गरम परोसें।",FV(0)]))
r.append(R(7206527,"बेक्ड पेस्टो चिकन और सिट्रस कूसकूस","जड़ी-बूटियों वाला पेस्टो चिकन कूसकूस के साथ परोसा गया है, जो स्टार्च वाले कार्बोहाइड्रेट का एक बढ़िया विकल्प है।","1","683 ग्राम",
["1 छोटा चम्मच जैतून का तेल","1 बिना हड्डी और बिना त्वचा का चिकन ब्रेस्ट","60 ग्राम साबुत गेहूँ का कूसकूस","150 मिलीलीटर चिकन स्टॉक","1 लाल प्याज़, बारीक कटा हुआ (150 ग्राम)","1 छोटी लाल शिमला मिर्च, बारीक कटी हुई (100 ग्राम)","1 बड़ा चम्मच ताज़ा अजमोद (पार्सले), कटा हुआ","1 नींबू का कद्दूकस किया हुआ ज़ेस्ट और रस","1 बड़ा चम्मच पेस्टो सॉस","ताज़ी पिसी काली मिर्च"],
["ओवन को 200°C/गैस मार्क 6 पर पहले से गरम करें।","नॉन-स्टिक पैन में तेल गरम करें, चिकन डालें और हर तरफ़ 2 मिनट तक भूरा होने तक तलें।","कूसकूस को ओवन में रखने योग्य डिश में डालें। स्टॉक, लाल प्याज़, लाल शिमला मिर्च, अजमोद तथा नींबू का ज़ेस्ट और रस एक साथ मिलाएँ, फिर इसे कूसकूस पर डालकर चलाएँ।","चिकन को कूसकूस के ऊपर रखें, फिर ऊपर से पेस्टो डालें और स्वाद अनुसार मसाला डालें।","डिश को फ़ॉइल से ढककर 20 मिनट तक बेक करें।","पक जाने पर कूसकूस को कांटे से फुला लें। गरम या ठंडा परोसें।"],
["शाकाहारी संस्करण के लिए चिकन की जगह मैरिनेट किया हुआ या स्मोक्ड टोफू डालकर देखें।","अगर लाल प्याज़ न मिले तो भूरा प्याज़ भी उतना ही अच्छा रहेगा।","पेस्टो की जगह कोई भी सन-ड्राइड टमाटर पेस्ट काम करेगा।","अगर आपके पास अजमोद या नींबू नहीं है तो चिंता न करें, इनके बिना भी यह रेसिपी उतनी ही स्वादिष्ट बनेगी।",FV(2)]))
r.append(R(7208015,"लिवर और प्याज़ के साथ नीप्स, टैटीज़ और बीन्स","लिवर में वसा कम और आयरन भरपूर होता है, और रंग-बिरंगा मैश इस क्लासिक ब्रिटिश पसंदीदा व्यंजन को पौष्टिकता से भर देता है।","4","564 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","4 प्याज़, कटे हुए","2 लहसुन की फांक, कुचली हुई","10 ग्राम मैदा + 2 छोटे चम्मच अतिरिक्त","एक अच्छी चुटकी काली मिर्च","1 पैकेट भेड़ का लिवर (450 ग्राम)","1 कम नमक वाला वेजिटेबल या भेड़ के मांस का स्टॉक क्यूब, 400 मिलीलीटर पानी में घुला हुआ","300 ग्राम स्वीड (शलजम की तरह की जड़), कटा हुआ","300 ग्राम शकरकंद, कटा हुआ","100 ग्राम पार्सनिप, कटा हुआ","300 ग्राम का पैकेट हरी बीन्स"],
["एक बड़े सॉसपैन में 1 छोटा चम्मच तेल गरम करें, प्याज़ डालें और 20 मिनट तक नियमित रूप से चलाते हुए नरम और कैरेमलाइज़ होने तक पकाएँ।","मैदे में काली मिर्च मिलाएँ और लिवर पर लपेट दें। फ्राइंग पैन में बचा हुआ तेल डालें, लिवर डालें और 3 मिनट तक भूरा करें। एक तरफ़ रख दें।","प्याज़ पक जाने पर सॉसपैन में लहसुन डालें और 2 छोटे चम्मच मैदा मिलाकर चलाएँ।","धीरे-धीरे स्टॉक और थोड़ी और काली मिर्च डालें, बार-बार चलाते हुए उबाल लाएँ और लिवर डालें। 5 मिनट और पकाएँ, जब तक कि लिवर नरम न हो जाए और सॉस गाढ़ा न हो जाए।","इस बीच, सब्ज़ियों को पानी में डुबोकर 15 मिनट तक नरम होने तक उबालें और पानी निकाल दें।","स्वीड, आलू और पार्सनिप को एक साथ मैश करें और लिवर तथा हरी बीन्स के साथ परोसें।"],
["सब्ज़ियों को उबालने के पानी को सॉस में इस्तेमाल करके सारे पोषक तत्व बचाएँ। आप सब्ज़ियाँ पहले पका सकते हैं और लिवर तैयार होने पर दोबारा गरम कर सकते हैं।","यह बछड़े, सूअर या मुर्गे के लिवर के साथ भी अच्छा बनता है।","फ्रीज़ करने के निर्देश: सब्ज़ियों और लिवर को अलग-अलग फ्रीज़ करें। फ्रिज में या माइक्रोवेव में पिघलाएँ। पूरी तरह भाप निकलने तक गरम होने तक दोबारा गरम करें।",FV(5)]))
r.append(R(7209689,"स्वादिष्ट परतदार आलू","यह क्लासिक बेक आपके आलुओं में नई जान डाल देगा और एक स्वादिष्ट साइड डिश बनेगा।","4","260 ग्राम",
["1.25 किलो पतले कटे हुए आलू","3 फांक कटा हुआ लहसुन","1 बड़ा चम्मच ताज़ा थाइम","2 बड़े चम्मच जैतून का तेल"],
["एक बड़ी, हल्की चिकनाई लगी ओवन-प्रूफ़ डिश में कटे हुए आलू, कटा लहसुन और ताज़ा थाइम की परतें लगाएँ।","जैतून का तेल और 200 मिलीलीटर पानी मिलाएँ, मसाला डालें और आलुओं पर डालें।","फ़ॉइल से ढककर 170ºC/गैस 3 पर 1 घंटे तक बेक करें और पकाने के आधे समय में फ़ॉइल हटा दें।"],
["आप इसमें पतले कटे प्याज़ की परतें भी लगा सकते हैं।","अधिक स्वाद के लिए पानी की जगह स्टॉक इस्तेमाल करें या फ़ॉइल हटाते समय ऊपर से थोड़ा कद्दूकस किया चेडर चीज़ डालें।","आप इसे स्वीड या शकरकंद जैसी दूसरी जड़ वाली सब्ज़ियों के साथ भी बना सकते हैं।","पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में या माइक्रोवेव में पिघलाएँ और पूरी तरह भाप निकलने तक गरम होने तक दोबारा गरम करें।",FV(0)]))
r.append(R(7211263,"सुपर सोबा नूडल्स","यह 'वन-पॉट' स्टर-फ्राई बाहर खाने का हमारे परिवार का विकल्प है, क्योंकि आप इसे झटपट बनाकर कुछ ही मिनटों में स्वादिष्ट भोजन तैयार कर सकते हैं।","4","509 ग्राम",
["250 ग्राम सोबा नूडल्स","320 ग्राम टोफू","अपनी पसंद का स्प्रे तेल (वैकल्पिक)","1 गुच्छा हरी प्याज़ (स्प्रिंग अनियन), टुकड़ों में कटी हुई","250 ग्राम मिले-जुले मशरूम, कटे हुए","2 मिली-जुली शिमला मिर्च (हरी, लाल या पीली), लंबाई में कटी हुई","150 ग्राम मैंज टू (हरी मटर की फलियाँ), लंबाई में कटी हुई","1 प्याज़, कटा हुआ","1/2 बारीक कटी पत्तागोभी","1 बड़ा चम्मच ताज़ा अदरक, कद्दूकस किया हुआ","1 लहसुन की फांक, कुचली हुई","चुटकी भर चाइनीज़ फ़ाइव स्पाइस","1 छोटा चम्मच कम नमक वाला सोया सॉस","1 बड़ा चम्मच केचप","चुटकी भर चिली फ्लेक्स (वैकल्पिक)","1 बड़ा चम्मच ताज़ा धनिया, कटा हुआ"],
["नूडल्स को पैकेट के निर्देशों के अनुसार तैयार करें और एक तरफ़ रख दें।","टोफू को छोटे टुकड़ों में काटें और फ्राइंग पैन में सेंकें। यह ज़्यादा देर में भूरा नहीं होता, इसलिए ध्यान रखें।","अगर इस्तेमाल कर रहे हैं तो अपने फ्राइंग पैन में तेल स्प्रे करें। तेज़ आँच पर रखें और अदरक तथा लहसुन के साथ सारी सब्ज़ियाँ डालकर तेज़ी से पकाएँ।","चाइनीज़ फ़ाइव स्पाइस, सोया सॉस, केचप और अगर इस्तेमाल कर रहे हैं तो चिली डालें। पकाते हुए चलाते रहें, जब तक कि सब्ज़ियाँ अल डेंटे (हल्की कुरकुरी) न हो जाएँ।","पके हुए नूडल्स डालें, धनिये से सजाएँ और परोसें।"],
["यह रेसिपी Balance की कवर स्टार शिवाली ने मधुमेह से मुक्ति की अपनी यात्रा के हिस्से के रूप में बनाई है।",FV(3)]))
r.append(R(7212449,"मसालेदार कीमा और दाल भरी शिमला मिर्च","प्रोटीन से भरपूर यह भोजन ताज़े, कुरकुरे सलाद के साथ स्वादिष्ट लगता है।","2","418 ग्राम",
["1 छोटा प्याज़, कटा हुआ","200 ग्राम कम वसा वाला बीफ़ कीमा (5% वसा)","1 छोटा चम्मच पिसा जीरा","चुटकी भर लाल मिर्च (केयेन पेपर)","400 ग्राम का डिब्बा भूरी/हरी दाल","200 ग्राम का डिब्बा कटे हुए टमाटर","1 बड़ा चम्मच टमाटर प्यूरी","2 बड़े चम्मच पुराना चेडर चीज़, कद्दूकस किया हुआ","1 पीली शिमला मिर्च, आधी कटी हुई और बीज निकाली हुई","1 लाल शिमला मिर्च, आधी कटी हुई और बीज निकाली हुई"],
["ओवन को 200ºC/गैस 6 पर पहले से गरम करें। प्याज़ और कीमा को एक मध्यम फ्राइंग पैन में डालें और 5-6 मिनट तक कीमा भूरा होने तक भूनें।","लाल शिमला मिर्च और चीज़ को छोड़कर बाकी सारी सामग्री डालें, उबाल लाएँ और 10 मिनट तक हल्की आँच पर पकाएँ।","शिमला मिर्च के आधे हिस्सों को ओवन-प्रूफ़ डिश में रखें, मिश्रण को उनमें बराबर बाँटकर भरें और ऊपर से चीज़ छिड़कें।","फ़ॉइल से ढककर 45 मिनट तक पकाएँ, जब तक कि शिमला मिर्च नरम न हो जाए।","फ़ॉइल हटाएँ और 10 मिनट और पकाएँ, जब तक कि चीज़ सुनहरा न हो जाए।"],
["आप इस कीमे को खोखले किए हुए मैरो (लौकी जैसी सब्ज़ी) के छल्लों या बड़े चपटे मशरूम में भरने के लिए इस्तेमाल कर सकते हैं।","भेड़ का कीमा, सूअर का कीमा, टर्की का कीमा या शाकाहारी मांस विकल्प भी इस रेसिपी के साथ अच्छे लगते हैं।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में या माइक्रोवेव में पिघलाएँ और पूरी तरह भाप निकलने तक गरम होने तक दोबारा गरम करें।",FV(4)]))
r.append(R(7212462,"हरी प्याज़ और बेबी गाजर के साथ सी ब्रीम मछली","प्लेस मछली के फ़िलेट्स को फिश स्टॉक में उबालकर सैमफ़ायर की परत पर परोसा गया है। यह एक हल्का और रसीला रात या दोपहर का भोजन है।","4","420 ग्राम",
["320 ग्राम शैंटनी गाजर, छँटी हुई और लंबाई में आधी कटी हुई","12 हरी प्याज़ (स्प्रिंग अनियन), 3 सेमी के टुकड़ों में कटी हुई","10 ग्राम सोआ (डिल), मोटा कटा हुआ, साथ में परोसने के लिए 4 टहनियाँ","1 कम नमक वाला वेजिटेबल स्टॉक क्यूब, 500 मिलीलीटर पानी में घुला हुआ","4 ब्रीम मछली के फ़िलेट (प्रत्येक लगभग 150 ग्राम)","110 ग्राम सैमफ़ायर","2 छोटे चम्मच कॉर्नफ़्लोर, 1 बड़े चम्मच स्किम्ड दूध में घुला हुआ","1 बड़ा चम्मच 0% वसा वाला ग्रीक दही","एक अच्छी चुटकी ताज़ी पिसी काली मिर्च","परोसने के लिए 4 नींबू की फांकें"],
["गाजर को पैन में डालें, उबलता पानी डालकर ढक दें, फिर ढक्कन लगाकर उबाल लाएँ। आँच कम करें और 12-15 मिनट तक गाजर नरम होने तक पकाएँ।","इस बीच, एक बड़े फ्राइंग पैन में हरी प्याज़ और एक चौथाई सोआ डालें और मछली के फ़िलेट्स उनके ऊपर रखें। स्टॉक डालें और हल्का उबाल लाएँ। पैन को ढक दें, अगर आपके पास बड़ा ढक्कन नहीं है तो फ़ॉइल से ढकें, फिर 5-6 मिनट तक हल्की आँच पर पकाएँ और देखें कि मछली अंदर तक पक गई है।","मछली को ध्यान से पैन से निकालें, गरम प्लेट में रखें और ढक दें।","सैमफ़ायर को हरी प्याज़ और स्टॉक में डालें, फिर सैमफ़ायर को ब्लांच करने के लिए 2 मिनट पकाएँ। स्टॉक को निथार लें और मध्यम आँच पर दूसरे सॉसपैन में डालें। सैमफ़ायर और हरी प्याज़ को एक तरफ़ रख दें।","गाजर का पानी निकालकर फेंक दें, फिर गाजर, सैमफ़ायर और हरी प्याज़ को परोसने के कटोरों या प्लेटों में डालें। अंत में मछली को ऊपर रखें।","उबलते स्टॉक में कॉर्नफ़्लोर मिलाएँ और गाढ़ा होने तक चलाते रहें, फिर बचा हुआ सोआ और दही डालें। अच्छी तरह मिलाएँ, फिर मछली पर डालें। काली मिर्च छिड़कें और नींबू की फांक तथा सोआ की टहनी के साथ परोसें।"],
["आप कोई भी गाजर इस्तेमाल कर सकते हैं, बस उसे छीलकर लंबे टुकड़ों में काट लें।","यह सैल्मन, हैडॉक, कॉड या तिलापिया के साथ भी अच्छा बनता है।",FV(1)]))
r.append(R(7212635,"ब्लैकबेरी और सेब का केक","हल्के साबुत गेहूँ के केक के मिश्रण में ब्लैकबेरी और सेब।","12","73 ग्राम",
["2 सेब","2 मध्यम अंडे","1 छोटा चम्मच वनीला एक्सट्रैक्ट","75 ग्राम बारीक पिसी चीनी (कैस्टर शुगर)","100 मिलीलीटर रेपसीड तेल (चिकनाई लगाने के लिए 1 छोटा चम्मच इस्तेमाल करें)","150 ग्राम साबुत गेहूँ का आटा","1 छोटा चम्मच बेकिंग पाउडर","150 ग्राम ब्लैकबेरी"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। 2 पाउंड के लोफ़ टिन (लगभग 27 सेमी x 12 सेमी) में चिकनाई लगाने के लिए रेपसीड तेल का 1 छोटा चम्मच इस्तेमाल करें।","बिना छिले सेबों को कटोरे में कद्दूकस करें और बीच का हिस्सा फेंक दें।","कटोरे में अंडे, वनीला एक्सट्रैक्ट, कैस्टर शुगर और तेल डालें और फेंट लें।","आटा और बेकिंग पाउडर डालकर अच्छी तरह मिलाएँ। ब्लैकबेरी को धीरे से मिलाएँ।","मिश्रण को लोफ़ टिन में डालें और 25 मिनट तक सख़्त और सुनहरा होने तक बेक करें। अगर ज़्यादा भूरा होने लगे तो 20 मिनट बाद फ़ॉइल से ढक दें। केक तब पक जाता है जब बीच में चाकू डालने पर वह साफ़ बाहर आए।"],
["आप नींबू या बादाम जैसे दूसरे एसेंस डाल सकते हैं या संतरे या नींबू का कद्दूकस किया हुआ ज़ेस्ट मिला सकते हैं।","इस रेसिपी में कोई भी बेरी चलेगी, जैसे ब्लैकबेरी की जगह रास्पबेरी। आप पिघलाई हुई जमी हुई बेरी भी इस्तेमाल कर सकते हैं।","फ़्रीज़र बैग में, फ़ॉइल या ग्रीसप्रूफ़ पेपर में लपेटकर, तीन महीने तक फ्रीज़ करें। लेबल लगाना न भूलें।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। स्लाइस काटें और फ्रीज़ करने के लिए फ़ॉइल में लपेटें। फिर आप ज़रूरत के अनुसार स्लाइस इस्तेमाल कर सकते हैं।"]))
r.append(R(7212684,"क्रीमी लीक और अजमोद सॉस में टर्की","कम वसा वाले क्रीमी सॉस में पकाया गया रसीला दुबला टर्की ब्रेस्ट, जिसमें लीक और अजमोद भरपूर मात्रा में हैं। हफ़्ते के बीच के दिनों के लिए एक बढ़िया रात का खाना।","4","284 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","4 टर्की एस्कैलोप, कटे हुए","2 लीक, कटे हुए","3 लहसुन की फांकें, कुचली हुई","एक अच्छी चुटकी सफ़ेद मिर्च","1 छोटा चम्मच डिजॉन सरसों","1 बड़ा चम्मच मैदा","100 मिलीलीटर स्किम्ड दूध","75 ग्राम एक्स्ट्रा-लाइट क्रीम चीज़","25 ग्राम अजमोद (पार्सले), कटा हुआ"],
["फ्राइंग पैन में 1 छोटा चम्मच तेल गरम करें और टर्की डालें। बाहर से भूरा करने के लिए हर तरफ़ 2 मिनट तक तलें। फिर उन्हें प्लेट में रखें, फ़ॉइल से ढककर एक तरफ़ रख दें और निकला हुआ रस बचाकर रखें।","उसी पैन में बचा हुआ 1 छोटा चम्मच तेल डालें और लीक डालें। नियमित रूप से चलाते हुए 5 मिनट तक हल्की आँच पर तलें, जब तक कि वे नरम न होने लगें, लेकिन उन्हें भूरा न होने दें।","लहसुन, सफ़ेद मिर्च, मैदा और सरसों डालें और अच्छी तरह मिलाएँ ताकि लीक पर लिपट जाएँ, फिर धीरे-धीरे 200 मिलीलीटर पानी मिलाएँ जब तक कि यह गाढ़ा होना शुरू न हो जाए।","धीरे-धीरे दूध मिलाएँ और लीक नरम होने तक पकाते और चलाते रहें। अगर सॉस ज़्यादा गाढ़ा हो जाए तो थोड़ा और दूध मिला दें।","टर्की एस्कैलोप को उनके निकले हुए रस के साथ वापस पैन में डालें और 2-3 मिनट तक पकाएँ।","टर्की को निकाल लें और सॉस में क्रीम चीज़ और अजमोद डालकर अच्छी तरह मिलाएँ। इसे एस्कैलोप पर डालें और मौसमी सब्ज़ियों के साथ परोसें।"],
["आप इस रेसिपी को सूअर के एस्कैलोप या चिकन ब्रेस्ट के साथ भी इस्तेमाल कर सकते हैं। यह कॉड या सैल्मन के साथ भी अच्छी लगती है।","अजमोद की जगह टैरागन, धनिया या सोआ जैसी अलग जड़ी-बूटियाँ डालकर देखें।","शाकाहारी संस्करण के लिए टर्की की जगह 400 ग्राम साबुत मशरूम इस्तेमाल करें",FV(1)]))
r.append(R(7212729,"चेरी और चॉकलेट डेज़र्ट पॉट","स्वादों का यह स्वादिष्ट मेल एक बेहतरीन सेहतमंद मीठा व्यंजन बनाता है।","4","109 ग्राम",
["225 ग्राम ताज़ी चेरी","2 बड़े चम्मच कृत्रिम स्वीटनर","1 समतल छोटा चम्मच कॉर्नफ़्लोर, 1 बड़े चम्मच ठंडे पानी में घुला हुआ","100 ग्राम क्वार्क या कम वसा वाला सॉफ़्ट चीज़","2 बड़े चम्मच स्किम्ड दूध","आधा समतल छोटा चम्मच वनीला एक्सट्रैक्ट",("चॉकलेट सॉस के लिए","25 ग्राम डार्क चॉकलेट, टुकड़ों में तोड़ी हुई"),("चॉकलेट सॉस के लिए","1 ढेर वाला छोटा चम्मच बिना चीनी वाला कोको पाउडर"),("चॉकलेट सॉस के लिए","आधा समतल छोटा चम्मच कॉर्नफ़्लोर, आधे बड़े चम्मच ठंडे पानी में घुला हुआ"),("चॉकलेट सॉस के लिए","1 समतल बड़ा चम्मच गोल्डन सिरप")],
["ताज़ी चेरी को आधा काटकर गुठली निकाल लें, सजाने के लिए 4 साबुत चेरी अलग रख लें।","एक छोटे पैन में 50 मिलीलीटर पानी और 1 बड़ा चम्मच कृत्रिम स्वीटनर के साथ डालें। 3-4 मिनट तक नरम होने तक हल्की आँच पर पकाएँ।","कॉर्नफ़्लोर और ठंडे पानी को मिलाएँ और चेरी में मिलाकर गाढ़ा होने तक चलाएँ।","आँच से उतारकर ठंडा करें, परत बनने से रोकने के लिए चलाते रहें।","एक कटोरे में क्वार्क, स्किम्ड दूध, वनीला एक्सट्रैक्ट और बचा हुआ स्वीटनर चिकना होने तक फेंटें।","चॉकलेट सॉस के लिए, डार्क चॉकलेट के टुकड़े पैन में डालें और बिना चीनी वाला कोको पाउडर, ठंडे पानी में घुला कॉर्नफ़्लोर और गोल्डन सिरप डालें। लगातार चलाते हुए चिकना होने तक गरम करें। ठंडा करें, परत बनने से रोकने के लिए चलाते रहें।","सब कुछ छोटे परोसने वाले गिलासों में चम्मच से डालें। हर एक के ऊपर एक चेरी रखें। ठंडा करके परोसें।"],
["ब्लूबेरी या ब्लैकबेरी भी चेरी जितनी ही अच्छी लगती हैं और इन्हें तैयार करना कहीं आसान है क्योंकि इनकी गुठली नहीं निकालनी पड़ती।","आप रास्पबेरी भी इस्तेमाल कर सकते हैं, लेकिन तब पकाने का समय घटाकर 2 मिनट कर दें।"]))
r.append(R(7215311,"चिकन, बटर बीन और लीक पाई","आलू की सुनहरी परत वाली यह पाई चिकन को चीज़ सॉस में टैरागन के साथ मिलाती है, जो पेट भरने वाले शाम के खाने के लिए स्वादों का शानदार मेल है।","4","525 ग्राम",
["1 बड़ा चम्मच तेल","2 बड़े बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट, टुकड़ों में कटे हुए","2 लीक, कटे हुए","2 बड़े चम्मच मैदा","600 मिलीलीटर सेमी-स्किम्ड दूध","2 बड़े चम्मच ताज़ा टैरागन, कटा हुआ","50 ग्राम पुराना चेडर, कद्दूकस किया हुआ","420 ग्राम का डिब्बा बटर बीन्स, छानी और धोई हुई","750 ग्राम आटेदार आलू, पके और मैश किए हुए","10 ग्राम वेजिटेबल ऑयल स्प्रेड"],
["ओवन को 200°C/गैस 6 पर पहले से गरम करें। एक सॉसपैन में तेल गरम करें, चिकन और लीक डालें और 4-5 मिनट तक तलें, जब तक कि चिकन भूरा होने न लगे।","मैदा और 450 मिलीलीटर दूध डालकर चलाएँ, उबाल लाएँ और गाढ़ा होने तक चलाते रहें। टैरागन, आधा चीज़ और बटर बीन्स मिलाएँ और अच्छी तरह मसाला डालें। इसे ओवन-प्रूफ़ डिश में डालें।","मैश किए हुए आलू, बचा हुआ दूध, मक्खन और बचा हुआ चीज़ मिलाएँ और चिकन के मिश्रण के ऊपर पाइप करें या चम्मच से फैला दें।","पाई को ओवन में रखें और 20-25 मिनट तक सुनहरी होने और बुलबुले उठने तक पकाएँ।"],
["साधारण आलू की जगह शकरकंद इस्तेमाल करके देखें, क्योंकि यह आपके दिन के 5 फल/सब्ज़ी के हिस्सों में गिना जाता है।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में पिघलाएँ और पूरी तरह भाप निकलने तक गरम होने तक दोबारा गरम करें।",FV(1)]))
r.append(R(7217497,"बेक्ड ओट्स","अगर आप ओवरनाइट ओट्स के शौकीन हैं, तो आपको यह ओवन से निकला गरमागरम संस्करण पसंद आएगा। बेक्ड ओट्स का आरामदायक कटोरा दिन की शुरुआत करने का बेहतरीन तरीका है। इस रेसिपी को Slimming World के साथ साझेदारी में चुना गया है।","1","135 ग्राम",
["40 ग्राम सादे पोरिज ओट्स","3 समतल बड़े चम्मच स्किम्ड दूध","1 अंडा, फेंटा हुआ","½ छोटा चम्मच वनीला एक्सट्रैक्ट","¼ छोटा चम्मच पिसी दालचीनी"],
["अपने ओवन को 200°C/फ़ैन 180°C/गैस 6 पर पहले से गरम करें।","ओट्स, दूध, अंडा, वनीला और दालचीनी को एक छोटी, गहरी ओवन-प्रूफ़ डिश में डालें, जिसमें पकते समय मिश्रण के फूलने के लिए जगह बचे। अच्छी तरह मिलाएँ और ओवन के बीच में 20-25 मिनट तक पकाएँ, जब तक कि यह सुनहरा न हो जाए और छूने पर सख़्त न लगे।","ओवन से निकालें, 3 मिनट ठंडा करें और ऊपर से क्वार्क या दही, अपनी पसंद का फल और पुदीने की टहनी डालें।"],
["कृपया ध्यान दें कि इस रेसिपी की पोषण संबंधी जानकारी में क्वार्क या दही और बेरी शामिल नहीं हैं, क्योंकि ये वैकल्पिक टॉपिंग हैं।",FV(0)]))
r.append(R(7217871,"बेक्ड सी बास और भुनी लाल शिमला मिर्च","यह सरल और स्वादिष्ट व्यंजन रसीली सी बास मछली को भूमध्यसागरीय स्वाद के साथ जोड़ता है।","4","503 ग्राम",
["600 ग्राम छीले हुए आलू, पतले कटे हुए (लगभग 1 सेमी)","4 प्लम टमाटर, छिलका उतारे हुए और चार भागों में कटे हुए","2 लाल और 2 नारंगी शिमला मिर्च, बीज निकाली हुई और टुकड़ों में कटी हुई","8 लहसुन की फांकें, हर एक तीन भागों में कटी हुई","2 लाल मिर्च, पतली कटी हुई","ऑरिगैनो की 4 छोटी टहनियाँ (या 1 छोटा चम्मच सूखा)","4 बड़े चम्मच जैतून का तेल","4 x 90 ग्राम सी बास, साफ़ की हुई और छँटी हुई","50 ग्राम रॉकेट (अरुगुला) पत्तियाँ","एक चुटकी काली मिर्च"],
["ओवन को 200°C/गैस 6 पर पहले से गरम करें। आलुओं को उबलते पानी के पैन में 7 मिनट के लिए डालें।","आलुओं का पानी निकालें और एक बड़ी रोस्टिंग डिश में एक कतार में रखें (मछली के लिए बिस्तर की तरह), दोनों तरफ़ जगह छोड़ें।","टमाटरों को आलुओं पर फैलाएँ, फिर लाल और पीली शिमला मिर्च को आलुओं के दोनों ओर रखें और लहसुन, मिर्च, ऑरिगैनो की टहनियाँ और जैतून का तेल छिड़कें, 1 बड़ा चम्मच जैतून का तेल बचाकर रखें। 30 मिनट तक बेक करें और समान रूप से पकाने के लिए आधे समय में डिश को घुमा दें।","इस बीच, मछली के हर तरफ़ 5-6 चीरे लगाएँ, त्वचा पर बचा हुआ जैतून का तेल मलें और नमक तथा काली मिर्च डालें। मछली को आलुओं के ऊपर रखें।","डिश को वापस ओवन में रखें और 20-25 मिनट और बेक करें (मछली के आकार के अनुसार), फिर से आधे समय में डिश को घुमाएँ, जब तक कि मछली अंदर तक पक न जाए। भुनी हुई सब्ज़ियों के साथ परोसें।"],
["यह रेसिपी ट्राउट या ब्रीम जैसी दूसरी साबुत मछलियों के साथ अच्छी बनती है।","यह सैल्मन स्टेक या किसी भी सफ़ेद मछली के स्टेक के साथ शानदार लगती है, खासकर उन लोगों के लिए जिन्हें मछली के कांटे पसंद नहीं। अगर साबुत मछली की जगह स्टेक या फ़िलेट इस्तेमाल कर रहे हैं, तो सब्ज़ियों के पकने का समय 10 मिनट बढ़ा दें और मछली के आकार के अनुसार मछली के पकने का समय घटाकर 15 मिनट कर दें।","यह डिनर पार्टी के लिए एक बढ़िया व्यंजन है।",FV(3)]))
save(1,r)
